('c0810200-0000-4000-8000-000000000040', 'الوحدة الثانية: زيت', 'دروس الوحدة: استماع (الزيتون غذاء وهوية)؛ قراءة (زيت)؛ نص شعري (على جذع زيتونة)؛ قواعد (اللازم والمتعدي)؛ بلاغة (علم البديع (الجناس))؛ إملاء (حالات خاصة في كتابة الهمزة المتوسطة)؛ خط (تدريبات على الخط العربي)؛ تعبير (تحليل الفقرة)', 8, '6 ساعات', '#00695c', 'award', 2, TRUE, 'الصف الثامن', 'الفصل الأول', '', '', 'published', FALSE, TRUE, 'الجميع'),
('c0810300-0000-4000-8000-000000000041', 'الوحدة الثالثة: صناعة النجاح وتجاوز الفشل', 'دروس الوحدة: استماع (الذكاء)؛ قراءة (صناعة النجاح وتجاوز الفشل)؛ قواعد (صور الفاعل والمفعول به)؛ إملاء (تدريبات على الهمزة المتوسطة)؛ خط (تدريبات على الخط العربي)؛ تعبير (تطبيق عملي على تحليل الفقرة)', 6, '5 ساعات', '#2e7d32', 'sparkles', 3, TRUE, 'الصف الثامن', 'الفصل الأول', '', '', 'published', FALSE, TRUE, 'الجميع'),
