('c0810500-0000-4000-8000-000000000043', 'الوحدة الخامسة: الرملة', 'دروس الوحدة: استماع (الأطفال الكبار)؛ قراءة (الرملة)؛ قواعد (المبني للمعلوم والمبني للمجهول)؛ إملاء (الألف اللينة في أواخر الأفعال (إملاء اختباري))؛ خط (تدريبات على الخط العربي)؛ تعبير (كتابة فقرتين)', 6, '5 ساعات', '#8a508f', 'landmark', 5, TRUE, 'الصف الثامن', 'الفصل الأول', '', '', 'published', FALSE, TRUE, 'الجميع'),
('c0810600-0000-4000-8000-000000000044', 'الوحدة السادسة: لماذا؟', 'دروس الوحدة: استماع (الياسمين الدمشقي)؛ قراءة (لماذا؟)؛ نص شعري (لنا الصدر)؛ قواعد (بناء فعل الأمر)؛ إملاء (الألف اللينة في الأسماء فوق الثلاثية)؛ بلاغة (المحسنات اللفظية (السجع))؛ خط (تدريبات على الخط العربي)؛ تعبير (كتابة فقرتين)', 8, '6 ساعات', '#a85d3d', 'leaf', 6, TRUE, 'الصف الثامن', 'الفصل الأول', '', '', 'published', FALSE, TRUE, 'الجميع'),
