('c0820800-0000-4000-8000-000000000054', 'الوحدة الثامنة: مواقف وطرائف', 'دروس الوحدة: استماع (أدب الفكاهة)؛ قراءة (مواقف وطرائف)؛ قواعد (تدريبات على إن وأخواتها)؛ إملاء (مراجعة عامة - تدريبات)؛ خط (تدريبات على الخط العربي)؛ تعبير (تدريب على الرسالة الإخوانية)', 6, '5 ساعات', '#a85d3d', 'shield-check', 8, TRUE, 'الصف الثامن', 'الفصل الثاني', '', '', 'published', FALSE, TRUE, 'الجميع')
INSERT INTO public.lessons (id, course_id, title, description, position, content, published, lesson_type, cover_url, images, html_content, html_file_url, status, is_locked, is_visible, grade, term)
VALUES
('d1010101-0000-4000-8000-000000000001', 'c1010100-0000-4000-8000-000000000001', 'الكلمة مفتاح القلوب', 'درس مطالعة من الوحدة الأولى: الكلمة مفتاح القلوب — الصف العاشر · الفصل الأول', 1, '{"introduction":"«الكلمة مفتاح القلوب» — نقرأ النص قراءة فاهمة واعية: الفكرة العامة والأفكار الجزئية، المفردات والتراكيب، ثم أسئلة الفهم والاستيعاب.","mainText":"محاور الدرس: نقرأ النص قراءة فاهمة واعية: الفكرة العامة والأفكار الجزئية، المفردات والتراكيب، ثم أسئلة الفهم والاستيعاب.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'مطالعة', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف العاشر', 'الفصل الأول'),
('d1010102-0000-4000-8000-000000000002', 'c1010100-0000-4000-8000-000000000001', 'الحال (1)', 'درس قواعد من الوحدة الأولى: الكلمة مفتاح القلوب — الصف العاشر · الفصل الأول', 2, '{"introduction":"«الحال (1)» — نتعرف القاعدة وضابطها بالأمثلة والشواهد، ثم نطبق عليها بنماذج إعرابية وتدريبات متنوعة.","mainText":"محاور الدرس: نتعرف القاعدة وضابطها بالأمثلة والشواهد، ثم نطبق عليها بنماذج إعرابية وتدريبات متنوعة.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'قواعد', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف العاشر', 'الفصل الأول'),
('d1010103-0000-4000-8000-000000000003', 'c1010100-0000-4000-8000-000000000001', 'التشبيه (1)', 'درس بلاغة من الوحدة الأولى: الكلمة مفتاح القلوب — الصف العاشر · الفصل الأول', 3, '{"introduction":"«التشبيه (1)» — ندرك سر الجمال البلاغي وأثره في المعنى: التعريف، الأركان أو الأنواع، الشواهد، ثم التطبيق والتدريب.","mainText":"محاور الدرس: ندرك سر الجمال البلاغي وأثره في المعنى: التعريف، الأركان أو الأنواع، الشواهد، ثم التطبيق والتدريب.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'بلاغة', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف العاشر', 'الفصل الأول'),
('d1010104-0000-4000-8000-000000000004', 'c1010100-0000-4000-8000-000000000001', 'المقالة', 'درس تعبير من الوحدة الأولى: الكلمة مفتاح القلوب — الصف العاشر · الفصل الأول', 4, '{"introduction":"«المقالة» — نتعلم خطوات الكتابة: التخطيط وجمع الأفكار، العرض المرتب بالشواهد، ثم المراجعة والتحسين.","mainText":"محاور الدرس: نتعلم خطوات الكتابة: التخطيط وجمع الأفكار، العرض المرتب بالشواهد، ثم المراجعة والتحسين.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'تعبير', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف العاشر', 'الفصل الأول'),
('d1010201-0000-4000-8000-000000000005', 'c1010200-0000-4000-8000-000000000002', 'القدس روح فلسطين', 'درس مطالعة من الوحدة الثانية: القدس روح فلسطين — الصف العاشر · الفصل الأول', 1, '{"introduction":"«القدس روح فلسطين» — نقرأ النص قراءة فاهمة واعية: الفكرة العامة والأفكار الجزئية، المفردات والتراكيب، ثم أسئلة الفهم والاستيعاب.","mainText":"محاور الدرس: نقرأ النص قراءة فاهمة واعية: الفكرة العامة والأفكار الجزئية، المفردات والتراكيب، ثم أسئلة الفهم والاستيعاب.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'مطالعة', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف العاشر', 'الفصل الأول'),
('d1010202-0000-4000-8000-000000000006', 'c1010200-0000-4000-8000-000000000002', 'مرثية بيت المقدس', 'درس نص شعري من الوحدة الثانية: القدس روح فلسطين — الصف العاشر · الفصل الأول', 2, '{"introduction":"«مرثية بيت المقدس» — نتذوق النص الشعري: الفكرة والعاطفة، الصور الفنية والموسيقا، المفردات، ثم التحليل والحفظ والأسئلة.","mainText":"محاور الدرس: نتذوق النص الشعري: الفكرة والعاطفة، الصور الفنية والموسيقا، المفردات، ثم التحليل والحفظ والأسئلة.","summary":"خلاصة الدرس وتطبيقاته — تُستكمل الشواهد والتدريبات التفصيلية من لوحة الأستاذ."}'::jsonb, TRUE, 'شعر', '', '[]'::jsonb, '', '', 'published', FALSE, TRUE, 'الصف العاشر', 'الفصل الأول'),
