-- ====================================================================
-- منصة أرض اللغة — منهاج الكتب الجديدة (2026-09-30)
-- الصفوف: الثامن / التاسع / العاشر × الفصلان الأول والثاني
-- المحتوى: 54 وحدة + 300 درس — العاشر (9+9)، التاسع (10+10)، الثامن (8+8)
--
-- طريقة التنفيذ: نفّذ الملف كاملاً في Supabase SQL Editor (مرة واحدة).
-- المتطلبات: ملف sql_curriculum_v2.sql (الأعمدة) — أما البوابات grade_gates فموجودة
--   مفتوحة افتراضياً (99) لكل صف وفصل، والوحدات الجديدة بترتيب 1-10 تظهر مفتوحة فوراً.
-- آمن إعادة التنفيذ: ON CONFLICT DO NOTHING — لا يمس أي تعديل للأستاذ لاحقاً.
-- ملاحظات: درسا أقيم ذاتي والمشروع ضمن الوحدة الأخيرة من كل جزء (نوع تقويم).
--   درس المشروع بنوع تقويم لأن قائمة الأنواع المعتمدة في اللوحة لا تحوي نوع مشروع.
-- ====================================================================

-- ── 1) الوحدات (54) ──
ON CONFLICT (id) DO NOTHING;

-- ── 2) دروس الصف العاشر · الفصل الأول (43 درساً) ──
ON CONFLICT (id) DO NOTHING;

-- ── 2) دروس الصف العاشر · الفصل الثاني (35 درساً) ──
ON CONFLICT (id) DO NOTHING;

-- ── 2) دروس الصف التاسع · الفصل الأول (54 درساً) ──
ON CONFLICT (id) DO NOTHING;

-- ── 2) دروس الصف التاسع · الفصل الثاني (52 درساً) ──
ON CONFLICT (id) DO NOTHING;

-- ── 2) دروس الصف الثامن · الفصل الأول (57 درساً) ──
ON CONFLICT (id) DO NOTHING;

-- ── 2) دروس الصف الثامن · الفصل الثاني (59 درساً) ──
ON CONFLICT (id) DO NOTHING;

-- ── 3) تحقق بعد التنفيذ ──
-- أ) عدد الوحدات لكل صف وفصل (المتوقع: العاشر 9+9، التاسع 10+10، الثامن 8+8)
SELECT grade, term, COUNT(*) AS units, SUM(lessons_count) AS lessons FROM public.courses GROUP BY grade, term ORDER BY grade, term;
-- ب) دروس بلا وحدة (يجب أن تكون 0)
SELECT COUNT(*) AS orphan_lessons FROM public.lessons WHERE course_id NOT IN (SELECT id FROM public.courses);
-- ج) وحدات عداد دروسها غير مطابق (يجب أن تكون 0)
SELECT COUNT(*) AS bad_counts FROM public.courses c WHERE c.lessons_count <> (SELECT COUNT(*) FROM public.lessons l WHERE l.course_id = c.id);

-- تم بحمد الله — نفّذ الملف كاملاً في Supabase SQL Editor
